"use client"

import { useLayoutEffect, useRef } from "react"
import Link from "next/link"
import gsap from "gsap"

import { cn } from "@/lib/utils"

import type { HeroV7Cta } from "./config"
import { heroV7Content } from "./config"

const CHAR_STAGGER = 0.03
const DURATION = 0.45
const EASE = "power3.out"

function playIn(row1: HTMLElement[], row2: HTMLElement[]) {
  gsap.killTweensOf([...row1, ...row2])
  gsap.to(row1, {
    yPercent: -100,
    duration: DURATION,
    stagger: CHAR_STAGGER,
    ease: EASE,
    overwrite: "auto",
  })
  gsap.to(row2, {
    yPercent: 0,
    duration: DURATION,
    stagger: CHAR_STAGGER,
    ease: EASE,
    overwrite: "auto",
  })
}

function playOut(row1: HTMLElement[], row2: HTMLElement[]) {
  gsap.killTweensOf([...row1, ...row2])
  gsap.to(row1, {
    yPercent: 0,
    duration: DURATION,
    stagger: { each: CHAR_STAGGER, from: "end" },
    ease: EASE,
    overwrite: "auto",
  })
  gsap.to(row2, {
    yPercent: 100,
    duration: DURATION,
    stagger: { each: CHAR_STAGGER, from: "end" },
    ease: EASE,
    overwrite: "auto",
  })
}

function useStaggerCtaAnimation(label: string) {
  const linkRef = useRef<HTMLAnchorElement>(null)

  useLayoutEffect(() => {
    const link = linkRef.current
    if (!link) return

    const row1 = gsap.utils.toArray<HTMLElement>(
      ".hero-v7-cta__stagger-text:not(.hero-v7-cta__stagger-text--second) .hero-v7-cta__char",
      link
    )
    const row2 = gsap.utils.toArray<HTMLElement>(
      ".hero-v7-cta__stagger-text--second .hero-v7-cta__char",
      link
    )

    if (row1.length === 0 || row2.length === 0) return

    const reduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches
    if (reduced) {
      gsap.set([...row1, ...row2], { clearProps: "all" })
      return
    }

    gsap.set(row1, { yPercent: 0 })
    gsap.set(row2, { yPercent: 100 })

    let over = false
    let pressed = false

    const sync = () => {
      if (over || pressed) playIn(row1, row2)
      else playOut(row1, row2)
    }

    const onEnter = () => {
      over = true
      sync()
    }

    const onLeave = () => {
      over = false
      pressed = false
      sync()
    }

    const onDown = (event: PointerEvent) => {
      if (!event.isPrimary) return
      if (event.pointerType === "mouse" && event.button !== 0) return
      pressed = true
      if (event.pointerType === "touch" || event.pointerType === "pen") {
        try {
          link.setPointerCapture(event.pointerId)
        } catch {

        }
      }
      sync()
    }

    const onUp = (event: PointerEvent) => {
      pressed = false
      try {
        if (link.hasPointerCapture(event.pointerId)) {
          link.releasePointerCapture(event.pointerId)
        }
      } catch {

      }
      if (event.pointerType === "touch") over = false
      sync()
    }

    const onCancel = (event: PointerEvent) => {
      pressed = false
      try {
        if (link.hasPointerCapture(event.pointerId)) {
          link.releasePointerCapture(event.pointerId)
        }
      } catch {

      }
      sync()
    }

    link.addEventListener("pointerenter", onEnter)
    link.addEventListener("pointerleave", onLeave)
    link.addEventListener("pointerdown", onDown)
    link.addEventListener("pointerup", onUp)
    link.addEventListener("pointercancel", onCancel)

    return () => {
      link.removeEventListener("pointerenter", onEnter)
      link.removeEventListener("pointerleave", onLeave)
      link.removeEventListener("pointerdown", onDown)
      link.removeEventListener("pointerup", onUp)
      link.removeEventListener("pointercancel", onCancel)
      gsap.killTweensOf([...row1, ...row2])
    }
  }, [label])

  return linkRef
}

function StaggerChars({ chars }: { chars: string[] }) {
  return (
    <>
      {chars.map((char, i) => (
        <span
          key={`${char}-${i}`}
          className="hero-v7-cta__char inline-block will-change-transform"
        >
          {char === " " ? "\u00a0" : char}
        </span>
      ))}
    </>
  )
}

function FlipCtaButton({
  href,
  label,
  variant = "primary",
  className,
}: {
  href: string
  label: string
  variant?: "primary" | "secondary"
  className?: string
}) {
  const linkRef = useStaggerCtaAnimation(label)

  return (
    <Link
      ref={linkRef}
      href={href}
      className={cn(
        "group relative inline-flex min-h-10 items-center justify-center rounded-full border px-5.5 py-2 font-mono text-sm font-medium tracking-[0.12em] uppercase no-underline transition-[background-color,border-color,color] duration-250 ease-out outline-none",
        variant === "primary" &&
          "border-white/14 bg-[#141414] text-zinc-100 hover:border-blue-500/40 hover:bg-[#1f1f1f] focus-visible:shadow-[0_0_0_2px_color-mix(in_srgb,rgba(59,130,246,0.55)_55%,transparent)] active:border-blue-500/40 active:bg-[#1f1f1f]",
        variant === "secondary" &&
          "border-zinc-900/14 bg-zinc-100 text-zinc-900 hover:border-orange-500/40 hover:bg-zinc-50 focus-visible:shadow-[0_0_0_2px_color-mix(in_srgb,rgba(249,115,22,0.55)_55%,transparent)] active:border-orange-500/40 active:bg-zinc-50",
        className
      )}
      style={{ touchAction: "manipulation" }}
    >
      <span
        className={cn(
          "pointer-events-none absolute -inset-px rounded-[inherit] opacity-0 transition-opacity duration-350 ease-[cubic-bezier(0.22,1,0.36,1)] group-hover:opacity-100 group-focus-visible:opacity-100 group-active:opacity-100",
          variant === "primary" &&
            "shadow-[0_0_0_1px_rgba(59,130,246,0.65),0_0_16px_rgba(59,130,246,0.28),0_0_32px_color-mix(in_srgb,rgba(59,130,246,0.28)_65%,transparent)]",
          variant === "secondary" &&
            "shadow-[0_0_0_1px_rgba(249,115,22,0.65),0_0_16px_rgba(249,115,22,0.28),0_0_32px_color-mix(in_srgb,rgba(249,115,22,0.28)_65%,transparent)]"
        )}
        aria-hidden="true"
      />
      <span className="relative inline-block overflow-hidden leading-none">
        <span className="hero-v7-cta__stagger-text inline-flex flex-wrap justify-center gap-0">
          <StaggerChars chars={label.split("")} />
        </span>
        <span
          className="hero-v7-cta__stagger-text hero-v7-cta__stagger-text--second absolute inset-0 inline-flex justify-center"
          aria-hidden="true"
        >
          <StaggerChars chars={label.split("")} />
        </span>
      </span>
    </Link>
  )
}

export default function CtaButtons({
  primaryCta = heroV7Content.primaryCta,
  secondaryCta = heroV7Content.secondaryCta,
}: {
  primaryCta?: HeroV7Cta
  secondaryCta?: HeroV7Cta
}) {
  return (
    <div className="flex flex-row flex-wrap justify-center gap-3">
      <FlipCtaButton
        href={primaryCta.href}
        label={primaryCta.label}
        variant="primary"
        className="w-full sm:w-auto"
      />
      <FlipCtaButton
        href={secondaryCta.href}
        label={secondaryCta.label}
        variant="secondary"
        className="w-full sm:w-auto"
      />
    </div>
  )
}

"use client"

import {
  Bicycle,
  Circle,
  CookingPot,
  Receipt,
} from "@phosphor-icons/react"

import { cn } from "@/lib/utils"
import { Doordash } from "@/components/ui/svgs/doordash"
import { UberEats } from "@/components/ui/svgs/ubereats"

import { usePipelineDemoAnimation } from "./use-pipeline-demo-animation"
import {
  DELIVERY_PLATFORMS,
  DELIVERY_STAGES,
  getDeliveryPlatformState,
  getFooterPlatforms,
  getFooterStepActive,
  type DeliveryPlatformState,
  type PipelineStage,
} from "./pipeline-config"

const PLATFORM_LOGOS = {
  ubereats: UberEats,
  doordash: Doordash,
} as const

const STAGE_ICONS = {
  ingest: Receipt,
  transform: CookingPot,
  deliver: Bicycle,
} as const

type StageId = keyof typeof STAGE_ICONS

const PLATFORM_CHIP_STYLES: Record<DeliveryPlatformState, string> = {
  inactive: "[&_svg]:opacity-25",
  pending: "[&_svg]:opacity-40",
  queued:
    "border-blue-500/35 bg-blue-500/5 ring-2 ring-blue-500/15 [&_svg]:opacity-70",
  delivering:
    "border-orange-500/25 bg-orange-500/4 [&_svg]:opacity-50",
  delivered:
    "border-orange-500 bg-orange-500/8 ring-2 ring-orange-500/25 [&_svg]:opacity-100",
  complete:
    "border-orange-500/45 bg-orange-500/6 [&_svg]:opacity-100",
}

function StageNode({
  stageId,
  label,
  detail,
  active,
}: {
  stageId: StageId
  label: string
  detail: string
  active: boolean
}) {
  const Icon = STAGE_ICONS[stageId]

  return (
    <div
      className={cn(
        "flex min-h-24 flex-col items-center justify-center gap-1.5 rounded-xl border border-zinc-900/12 px-3 py-3 text-center transition-[border-color,box-shadow,color] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)] dark:border-white/12",
        stageId === "ingest" &&
          active &&
          "border-zinc-900/28 dark:border-white/28 [&_.hero-v7-pipeline__node-icon]:text-zinc-600 dark:[&_.hero-v7-pipeline__node-icon]:text-zinc-300",
        stageId === "transform" &&
          active &&
          "border-blue-500 ring-2 ring-blue-500/25 [&_.hero-v7-pipeline__node-icon]:text-blue-500",
        stageId === "deliver" &&
          active &&
          "border-orange-500 ring-2 ring-orange-500/25 [&_.hero-v7-pipeline__node-icon]:text-orange-500"
      )}
    >
      <span
        className="hero-v7-pipeline__node-icon inline-flex text-zinc-400 transition-colors duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]"
        aria-hidden
      >
        <Icon size={20} weight="duotone" />
      </span>
      <span
        className={cn(
          "text-sm font-medium tracking-tight text-foreground transition-colors duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]",
          active && stageId === "ingest" && "font-semibold",
          active &&
            stageId === "transform" &&
            "font-semibold text-blue-600 dark:text-blue-400",
          active &&
            stageId === "deliver" &&
            "font-semibold text-orange-600 dark:text-orange-400"
        )}
      >
        {label}
      </span>
      <span
        className={cn(
          "max-w-39 text-pretty font-mono text-xs leading-relaxed tracking-tight text-muted-foreground transition-colors duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]",
          active && "text-foreground/75"
        )}
      >
        {detail}
      </span>
    </div>
  )
}

function PlatformChip({
  chipId,
  label,
  state,
}: {
  chipId: keyof typeof PLATFORM_LOGOS
  label: string
  state: DeliveryPlatformState
}) {
  const Logo = PLATFORM_LOGOS[chipId]

  return (
    <span
      className={cn(
        "inline-flex items-center justify-center rounded-full border border-zinc-900/10 px-2.5 py-1.5 transition-[border-color,background-color,opacity,box-shadow] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)] dark:border-white/10",
        PLATFORM_CHIP_STYLES[state]
      )}
    >
      <Logo className="block size-5.5 w-auto transition-opacity duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]" />
      <span className="sr-only">{label}</span>
    </span>
  )
}

function isStageActive(stage: PipelineStage, id: StageId) {
  return stage === id
}

export default function PipelineDemo() {
  const { run, stage, activePlatforms, lineARef, lineBRef } =
    usePipelineDemoAnimation()

  const footerPlatforms = getFooterPlatforms(stage, run.platforms)
  const footerActive = getFooterStepActive(stage, run.platforms)

  return (
    <div
      className="mx-auto mt-2 w-full max-w-3xl text-left"
      aria-label="Live food delivery demo"
    >
      <div className="overflow-hidden rounded-2xl border border-zinc-900/10 bg-zinc-50 shadow-[0_24px_48px_-28px_rgba(24,24,27,0.18)] dark:border-white/10 dark:bg-[#141414] dark:shadow-[0_24px_48px_-28px_rgba(0,0,0,0.45)]">
        <header className="flex items-center justify-between gap-4 border-b border-zinc-900/8 px-4 py-3 text-xs dark:border-white/8">
          <div className="flex min-w-0 items-center gap-3">
            <span className="font-mono text-2.75 tracking-wider text-muted-foreground">
              {run.id}
            </span>
            <span className="inline-flex items-center gap-1.5 text-zinc-600 dark:text-zinc-300">
              <Circle
                className={cn(
                  "text-zinc-400 transition-colors duration-250 ease-out",
                  stage !== "idle" && "text-green-500"
                )}
                size={8}
                weight="fill"
                aria-hidden
              />
              <span className="font-mono text-2.75 tracking-wider uppercase">
                {stage === "idle" ? "Delivered" : "In progress"}
              </span>
            </span>
          </div>
          <span className="font-mono text-3.25 text-foreground tabular-nums">
            {run.etaMin}
            <span className="text-muted-foreground"> min</span>
          </span>
        </header>

        <div className="flex flex-col gap-3 px-4 pt-5 pb-4">
          <div className="relative z-1 grid grid-cols-1 items-start gap-3 sm:grid-cols-[minmax(0,1fr)_2.5rem_minmax(0,1fr)_2.5rem_minmax(0,1fr)] sm:items-stretch sm:gap-0">
            <StageNode
              stageId="ingest"
              label={DELIVERY_STAGES[0].label}
              detail={DELIVERY_STAGES[0].detail}
              active={isStageActive(stage, "ingest")}
            />

            <div
              ref={lineARef}
              className="hero-v7-pipeline__line hero-v7-pipeline__line--transform relative hidden h-0.5 self-center overflow-hidden rounded-full bg-zinc-900/8 sm:block dark:bg-white/8"
              aria-hidden
            />

            <StageNode
              stageId="transform"
              label={DELIVERY_STAGES[1].label}
              detail={DELIVERY_STAGES[1].detail}
              active={isStageActive(stage, "transform")}
            />

            <div
              ref={lineBRef}
              className="hero-v7-pipeline__line hero-v7-pipeline__line--deliver relative hidden h-0.5 self-center overflow-hidden rounded-full bg-zinc-900/8 sm:block dark:bg-white/8"
              aria-hidden
            />

            <StageNode
              stageId="deliver"
              label={DELIVERY_STAGES[2].label}
              detail={DELIVERY_STAGES[2].detail}
              active={isStageActive(stage, "deliver")}
            />
          </div>

          <div
            className="flex flex-wrap justify-center gap-2 pt-1"
            aria-label="Delivery apps"
          >
            {DELIVERY_PLATFORMS.map((chip) => (
              <PlatformChip
                key={chip.id}
                chipId={chip.id}
                label={chip.label}
                state={getDeliveryPlatformState(
                  chip.label,
                  run.platforms,
                  stage,
                  activePlatforms
                )}
              />
            ))}
          </div>
        </div>

        <footer className="flex flex-wrap items-center justify-center gap-x-2 gap-y-1.5 border-t border-zinc-900/8 px-4 py-3 font-mono text-sm leading-snug dark:border-white/8">
          <span
            className={cn(
              "transition-colors duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]",
              footerActive.order
                ? "font-medium text-foreground"
                : "text-muted-foreground"
            )}
          >
            {run.order}
          </span>
          <span className="text-zinc-400" aria-hidden>
            →
          </span>
          <span
            className={cn(
              "transition-colors duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]",
              footerActive.prep
                ? "font-medium text-blue-600 dark:text-blue-400"
                : "text-muted-foreground"
            )}
          >
            {run.prep}
          </span>
          <span className="text-zinc-400" aria-hidden>
            →
          </span>
          <span
            className={cn(
              "transition-colors duration-300 ease-[cubic-bezier(0.22,1,0.36,1)]",
              footerActive.platforms
                ? "font-medium text-orange-600 dark:text-orange-400"
                : "text-muted-foreground"
            )}
          >
            {footerPlatforms.text}
          </span>
        </footer>
      </div>
    </div>
  )
}

"use client"

import { useLayoutEffect, useRef, useState, useSyncExternalStore } from "react"
import gsap from "gsap"

import { DELIVERY_EXAMPLES, type PipelineStage } from "./pipeline-config"

function subscribeReducedMotion(onStoreChange: () => void) {
  const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
  mq.addEventListener("change", onStoreChange)
  return () => mq.removeEventListener("change", onStoreChange)
}

function getReducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

function getReducedMotionServer() {
  return false
}

const TIMING = {
  startDelay: 0.4,
  stageHold: 0.55,
  lineFill: 0.65,
  deliverPause: 0.15,
  betweenExamples: 0.85,
  resizeDebounce: 0.15,
} as const

export function usePipelineDemoAnimation() {
  const reducedMotion = useSyncExternalStore(
    subscribeReducedMotion,
    getReducedMotion,
    getReducedMotionServer
  )
  const lineARef = useRef<HTMLDivElement>(null)
  const lineBRef = useRef<HTMLDivElement>(null)
  const exampleIndexRef = useRef(0)
  const timelineRef = useRef<gsap.core.Timeline | null>(null)
  const delayedCallRef = useRef<gsap.core.Tween | null>(null)

  const [exampleIndex, setExampleIndex] = useState(0)
  const [stage, setStage] = useState<PipelineStage>("idle")
  const [activePlatforms, setActivePlatforms] = useState<string[]>([])

  const run = DELIVERY_EXAMPLES[exampleIndex]

  useLayoutEffect(() => {
    if (!reducedMotion) {
      return
    }

    const lineA = lineARef.current
    const lineB = lineBRef.current

    if (!lineA || !lineB) {
      return
    }

    gsap.set([lineA, lineB], { "--hero-v7-pipeline-line-progress": "100%" })
  }, [reducedMotion])

  useLayoutEffect(() => {
    if (reducedMotion) {
      return
    }

    const lineA = lineARef.current
    const lineB = lineBRef.current

    if (!lineA || !lineB) {
      return
    }

    let cancelled = false

    const stopAll = () => {
      timelineRef.current?.kill()
      timelineRef.current = null
      delayedCallRef.current?.kill()
      delayedCallRef.current = null
      gsap.killTweensOf([lineA, lineB])
    }

    const resetLines = () => {
      gsap.set([lineA, lineB], { "--hero-v7-pipeline-line-progress": "0%" })
    }

    const playExample = (index: number) => {
      if (cancelled) {
        return
      }

      stopAll()

      exampleIndexRef.current = index
      const current = DELIVERY_EXAMPLES[index]

      setExampleIndex(index)
      setStage("ingest")
      setActivePlatforms([])
      resetLines()

      const tl = gsap.timeline({
        onComplete: () => {
          if (cancelled) {
            return
          }
          const next = (index + 1) % DELIVERY_EXAMPLES.length
          delayedCallRef.current = gsap.delayedCall(
            TIMING.betweenExamples,
            () => playExample(next)
          )
        },
      })
      timelineRef.current = tl

      tl.call(() => setStage("ingest"))
        .to({}, { duration: TIMING.stageHold })
        .to(lineA, {
          "--hero-v7-pipeline-line-progress": "100%",
          duration: TIMING.lineFill,
          ease: "power2.out",
        })
        .call(() => setStage("transform"))
        .to({}, { duration: TIMING.stageHold })
        .to(lineB, {
          "--hero-v7-pipeline-line-progress": "100%",
          duration: TIMING.lineFill,
          ease: "power2.out",
        })
        .call(() => {
          setStage("deliver")
          setActivePlatforms([])
        })
        .to({}, { duration: TIMING.deliverPause })
        .call(() => setActivePlatforms(current.platforms))
        .to({}, { duration: TIMING.stageHold })
        .call(() => setStage("idle"))
    }

    delayedCallRef.current = gsap.delayedCall(TIMING.startDelay, () =>
      playExample(exampleIndexRef.current)
    )

    const onResize = () => {
      stopAll()
      delayedCallRef.current = gsap.delayedCall(TIMING.resizeDebounce, () =>
        playExample(exampleIndexRef.current)
      )
    }

    window.addEventListener("resize", onResize)

    return () => {
      cancelled = true
      stopAll()
      window.removeEventListener("resize", onResize)
    }
  }, [reducedMotion])

  if (reducedMotion) {
    return {
      run: DELIVERY_EXAMPLES[0],
      stage: "idle" as const,
      activePlatforms: DELIVERY_EXAMPLES[0].platforms,
      lineARef,
      lineBRef,
    }
  }

  return {
    run,
    stage,
    activePlatforms,
    lineARef,
    lineBRef,
  }
}

export type HeroV7Cta = {
  label: string
  href: string
}

export type HeroV7Content = {
  title: string
  description: string
  primaryCta: HeroV7Cta
  secondaryCta: HeroV7Cta
}

export const heroV7Content: HeroV7Content = {
  title: "Find your next delivery app partner for your business",
  description:
    "Take the order, prep the food, send it out on DoorDash or Uber Eats.",
