export type DeliveryPlatformId = (typeof DELIVERY_PLATFORMS)[number]["id"]

export type DeliveryPlatformState =
  | "inactive"
  | "pending"
  | "queued"
  | "delivering"
  | "delivered"
  | "complete"

export function getDeliveryPlatformState(
  platformLabel: string,
  orderPlatforms: string[],
  stage: PipelineStage,
  activePlatforms: string[]
): DeliveryPlatformState {
  if (!orderPlatforms.includes(platformLabel)) {
    return "inactive"
  }

  switch (stage) {
    case "idle":
      return "complete"
    case "ingest":
      return "pending"
    case "transform":
      return "queued"
    case "deliver":
      return activePlatforms.includes(platformLabel)
        ? "delivered"
        : "delivering"
    default:
      return "pending"
  }
}

export function getFooterPlatforms(
  stage: PipelineStage,
  orderPlatforms: string[]
) {
  const route = orderPlatforms.join(" + ")

  if (stage === "deliver" || stage === "idle") {
    return {
      text: route,
      highlighted: true,
    }
  }

  return {
    text: route,
    highlighted: false,
  }
}

export function getFooterStepActive(
  stage: PipelineStage,
  orderPlatforms: string[]
) {
  const platforms = getFooterPlatforms(stage, orderPlatforms)

  return {
    order: stage === "ingest",
    prep: stage === "transform",
    platforms: platforms.highlighted,
  }
}

.hero-v7-pipeline__line::after {
  content: "";
  position: absolute;
  inset: 0;
  width: var(--hero-v7-pipeline-line-progress, 0%);
  border-radius: inherit;
  background: #52525b;
  transition: width 0.05s linear;
}

.hero-v7-pipeline__line--transform::after {
  background: #3b82f6;
}

.hero-v7-pipeline__line--deliver::after {
  background: #f97316;
}

.dark .hero-v7-pipeline__line::after {
  background: #a1a1aa;
}

.dark .hero-v7-pipeline__line--transform::after {
  background: #60a5fa;
}

.dark .hero-v7-pipeline__line--deliver::after {
  background: #fb923c;
}

@media (prefers-reduced-motion: reduce) {
  .hero-v7-pipeline__line::after {
    width: 100%;
  }

  .hero-v7-cta__stagger-text--second {
    display: none;
  }

  .hero-v7-cta__char {
    will-change: auto;
  }
}
